module cc_lossy_valid_to_stream #(parameter Width=8)(input clk_i,rst_ni,clr_i,input valid_i,input[Width-1:0]data_i,output valid_o,input ready_i,output[Width-1:0]data_o,output busy_o);reg rp,wp;reg[1:0]cnt;reg[Width-1:0]mem[0:1];assign valid_o=(cnt!=0)||valid_i;assign data_o=(cnt==0&&valid_i)?data_i:mem[rp];assign busy_o=cnt!=0;always @(posedge clk_i or negedge rst_ni)if(!rst_ni)begin rp<=0;wp<=0;cnt<=0;end else if(clr_i)begin rp<=0;wp<=0;cnt<=0;end else begin if(valid_i&&(cnt!=0||!ready_i))begin if(cnt==2&&!ready_i)mem[wp]<=data_i /* MUTATION: overwrite wrong slot */;else begin mem[wp]<=data_i;wp<=wp+1;end end if(valid_i&&!(valid_o&&ready_i)&&cnt!=2)cnt<=cnt+1;else if(!valid_i&&valid_o&&ready_i)begin cnt<=cnt-1;rp<=rp+1;end end endmodule
